export function ComponentEditorEdgesPanel({
  draft,
  setDraft,
  hidden,
  previewLengthMm,
  previewWidthMm,
}: ComponentEditorEdgesPanelProps): ReactNode {
  const edgeStates: EdgeStates = {
    L1: draft.edgeL1,
    L2: draft.edgeL2,
    W1: draft.edgeW1,
    W2: draft.edgeW2,
  };

  const toggle = (side: EdgeSide) => {
    const key = `edge${side}` as (typeof EDGE_KEYS)[number];
    setDraft((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  // Prefer resolved preview dims when base is 0 / formulas present (R3-S2).
  const lengthMm =
    previewLengthMm != null && previewLengthMm > 0
      ? previewLengthMm
      : draft.lengthMm;
  const widthMm =
    previewWidthMm != null && previewWidthMm > 0
      ? previewWidthMm
      : draft.widthMm;

  return (
    <div
      role="tabpanel"
      id="component-editor-panel-edges"
      aria-labelledby="component-editor-tab-edges"
      hidden={hidden}
      data-testid="component-editor-panel-edges"
    >
      <p className="component-edges__intro">
        Tocá un borde de la placa para marcarlo como <strong>encintado</strong> por
        defecto. Los bordes encintados llevan cintilla en todas las piezas de este
        componente.
      </p>

      <PlankEdgeDiagram
        edges={edgeStates}
        onToggle={toggle}
        lengthMm={lengthMm}
        widthMm={widthMm}
      />

      <details className="component-edges__fallback">
        <summary>Lista de cantos</summary>
        <div
          className="module-edge-flags"
          role="group"
          aria-label="Cantos por defecto"
          data-testid="component-edges-group"
        >
          {(
            [
              ['edgeL1', 'L1', 'Largo arriba'],
              ['edgeL2', 'L2', 'Largo abajo'],
              ['edgeW1', 'W1', 'Ancho izquierda'],
              ['edgeW2', 'W2', 'Ancho derecha'],
            ] as const
          ).map(([key, label, sub]) => (
            <label key={key} className="component-edge-check">
              <input
                type="checkbox"
                checked={draft[key]}
                onChange={(e) =>
                  setDraft((prev) => ({ ...prev, [key]: e.target.checked }))
                }
              />
              <span>{label}</span>
              <span className="component-edge-check__sub">{sub}</span>
            </label>
          ))}
        </div>
      </details>
    </div>
  );
}

export function ComponentEditorOptionsPanel({
  draft,
  setDraft,
  optionGroups,
  hidden,
}: ComponentEditorOptionsPanelProps): ReactNode {
  const selected = draft.optionRoles
    .split(',')
    .map((s) => s.trim().toUpperCase())
    .filter(Boolean);

  // Exclusive selection: the binding role is single (#403). Clicking the
  // active chip clears it; clicking another replaces the previous binding.
  const toggle = (code: string) => {
    const upper = code.toUpperCase();
    const next = selected.includes(upper)
      ? selected.filter((c) => c !== upper)
      : [upper];
    setDraft((prev) => ({ ...prev, optionRoles: next.join(', ') }));
  };

  return (
    <div
      role="tabpanel"
      id="component-editor-panel-options"
      aria-labelledby="component-editor-tab-options"
      hidden={hidden}
      data-testid="component-editor-panel-options"
    >
      <p className="component-options__intro">
        Elegí qué selección de material sigue esta pieza. Una pieza de tablero
        sigue un único rol: todas las piezas con el mismo rol cambian juntas de
        material.
      </p>

      {hasAmbiguousOptionRoles(draft.optionRoles.split(',')) ? (
        <p
          className="component-options__warning"
          data-testid="component-options-ambiguity-warning"
          role="alert"
        >
          Este componente tiene varios roles declarados (
          {optionRolesSummary(selected, optionGroups)}). El motor usa sólo el
          primero y el resto quedaría sin efecto. Dejá un único rol.
        </p>
      ) : null}

      <div
        className="component-options__chips"
        role="group"
        aria-label="Roles de opción"
        data-testid="input-optionRoles"
      >
        {optionGroups.length === 0 ? (
          <p className="component-options__empty">
            No hay grupos de opciones definidos. Creá grupos en la sección
            correspondiente para asignarlos acá.
          </p>
        ) : (
          optionGroups.map((g) => {
            const active = selected.includes(g.code.toUpperCase());
            return (
              <button
                key={g.id}
                type="button"
                className={
                  'component-options__chip' +
                  (active ? ' component-options__chip--on' : '')
                }
                aria-pressed={active}
                data-testid={`option-role-${g.code}`}
                onClick={() => toggle(g.code)}

export function ModuleEditorStructurePanel({
  draft,
  setDraft,
  structures,
  selectedStructure,
  hidden,
}: ModuleEditorStructurePanelProps): ReactNode {
  return (
    <div
      className="module-editor__section"
      role="tabpanel"
      id="module-editor-panel-structure"
      aria-labelledby="module-editor-tab-structure"
      hidden={hidden}
      data-testid="module-editor-panel-structure"
    >
      <h4 className="module-editor__section-title">Estructura (cuerpo)</h4>
      <p className="module-editor__hint module-editor__hint--flush">
        El cuerpo se arma en Ingeniería → Estructuras. Acá elegís cuál usa este
        mueble y la medida base (obligatoria si hay estructura).
      </p>
      <div className="catalog-form__field">
        <label htmlFor="mod-structure">Estructura base</label>
        <select
          id="mod-structure"
          value={draft.structureId}
          onChange={(e) => {
            const sid = e.target.value;
            const struct = structures.find((s) => s.id === sid);
            setDraft((prev) => ({
              ...prev,
              structureId: sid,
              components: sid ? prev.components : [],
              ...(struct?.externalDims
                ? {
                    externalWidth: String(struct.externalDims.width),
                    externalHeight: String(struct.externalDims.height),
                    externalDepth: String(struct.externalDims.depth),
                  }
                : {}),
            }));
          }}
          data-testid="structure-picker"
        >
          <option value="">— Sin estructura —</option>
          {structures
            .filter((s) => s.active !== false)
            .map((s) => (
              <option key={s.id} value={s.id}>
                {s.code} — {s.name}
              </option>
            ))}
        </select>
        {selectedStructure ? (
          <StructureRevisionBadge
            structure={selectedStructure}
            testId="module-editor-selected-structure-revision"
          />
        ) : null}
      </div>
      {selectedStructure?.components &&
      selectedStructure.components.length > 0 ? (
        <p className="catalog-empty" data-testid="structure-body-hint">
          Esta estructura aporta {selectedStructure.components.length}{' '}
          componente
          {selectedStructure.components.length === 1 ? '' : 's'} de cuerpo. Los
          del mueble (puertas, entrepaños…) van en la pestaña Componentes.
        </p>
      ) : null}

export function ModuleEditorMeasuresPanel({
  draft,
  setDraft,
  selectedStructure,
  canMutate,
  hidden,
}: ModuleEditorMeasuresPanelProps): ReactNode {
  return (
    <div
      className="module-editor__section"
      role="tabpanel"
      id="module-editor-panel-measures"
      aria-labelledby="module-editor-tab-measures"
      hidden={hidden}
      data-testid="module-editor-panel-measures"
    >
      <ModuleMeasureSection
        presets={draft.presets}
        disabled={!canMutate}
        onPresetsChange={(presets) =>
          setDraft((prev) => ({ ...prev, presets }))
        }
        nextId={nextPresetId}
        canImportFromStructure={(selectedStructure?.presets?.length ?? 0) > 0}
        onImportFromStructure={() => {
          const fromStructure = (selectedStructure?.presets ?? []).map(
            (pr) => ({
              id: nextPresetId(),
              name: pr.name ?? '',
              width: pr.width,
              height: pr.height,
              depth: pr.depth,
            }),
          );
          setDraft((prev) => ({
            ...prev,
            presets: [...prev.presets, ...fromStructure],
          }));
        }}
        canSeedFromBase={
          Number(draft.externalWidth) > 0 &&
          Number(draft.externalHeight) > 0 &&
          Number(draft.externalDepth) > 0
        }
        onSeedFromBase={() => {
          const w = Number(draft.externalWidth);
          const h = Number(draft.externalHeight);
          const d = Number(draft.externalDepth);
          if (!(w > 0 && h > 0 && d > 0)) return;
          setDraft((prev) => ({
            ...prev,
            presets: [
              ...prev.presets,
              {
                id: nextPresetId(),
                name: 'Medida base',
                width: w,
                height: h,
                depth: d,
              },
            ],
          }));
        }}
      />
    </div>
  );
}

export function StructureEditorPresetsPanel({
  presets,
  exteriorDims,
  onAdd,
  onRemove,
  onUpdate,
  hidden,
}: StructureEditorPresetsPanelProps): ReactNode {
  const [dimErrors, setDimErrors] = useState<DimErrors>({});
  const canCopyExterior =
    exteriorDims.width > 0 &&
    exteriorDims.height > 0 &&
    exteriorDims.depth > 0;

  const validateDim = (
    presetId: string,
    key: DimKey,
    label: string,
    value: number,
  ) => {
    const invalid = Number.isNaN(value) || value <= 0;
    setDimErrors((prev) => ({
      ...prev,
      [presetId]: {
        ...prev[presetId],
        [key]: invalid ? `${label} debe ser mayor a 0.` : undefined,
      },
    }));
  };

  const copyExteriorInto = (presetId: string) => {
    onUpdate(presetId, {
      width: exteriorDims.width,
      height: exteriorDims.height,
      depth: exteriorDims.depth,
    });
    setDimErrors((prev) => {
      const next = { ...prev };
      delete next[presetId];
      return next;
    });
  };

  return (
    <div
      role="tabpanel"
      id="structure-editor-panel-presets"
      aria-labelledby="structure-editor-tab-presets"
      hidden={hidden}
      data-testid="structure-editor-panel-presets"
    >
      <div className="structure-editor-panel-header">
        <h4 className="module-editor__section-title">
          Presets de medidas ({presets.length})
        </h4>
        <button
          type="button"
          className="btn btn--small btn--primary"
          onClick={onAdd}
          data-testid="add-preset-btn"
        >
          <Plus size={14} strokeWidth={1.5} aria-hidden /> Agregar preset
        </button>
      </div>

      <p className="catalog-form__hint">
        Variantes de estirado para preview 3D e ingeniería. No son la lista
        comercial del mueble (eso vive en Muebles).
      </p>

      {presets.length === 0 ? (
        <div className="structure-presets-empty" data-testid="presets-empty">
          Sin presets de medida. Si no hay presets, la estructura usará su
          medida exterior (General) como referencia.
        </div>

