export const ProjectMeasureDefaults = memo(function ProjectMeasureDefaults(): ReactNode {
  const { project, modules, onUpdateMeasureDefaults } = useProjectDetail();

  if (!onUpdateMeasureDefaults || isProjectClosed(project.status)) {
    return null;
  }

  const typesInUse = Array.from(
    new Set(modules.map((m) => m.furnitureType ?? 'inferior')),
  ) as FurnitureType[];

  if (typesInUse.length === 0) return null;

  const handleUpdate = (
    type: FurnitureType,
    field: 'depth' | 'height',
    value: string,
  ) => {
    const prev = { ...(project.measureDefaults ?? {}) } as Record<
      FurnitureType,
      { depth?: number; height?: number } | undefined
    >;
    const typeEntry = prev[type] ? { ...prev[type]! } : {};
    const parsed = value.trim() === '' ? undefined : Number(value);

    if (field === 'depth') {
      if (parsed === undefined || Number.isNaN(parsed))
        delete typeEntry.depth;
      else typeEntry.depth = parsed;
    } else {
      if (parsed === undefined || Number.isNaN(parsed))
        delete typeEntry.height;
      else typeEntry.height = parsed;
    }

    if (typeEntry.depth === undefined && typeEntry.height === undefined) {
      delete prev[type];
    } else {
      prev[type] = typeEntry;
    }

    const hasAny = (Object.keys(prev) as FurnitureType[]).some(
      (k) => prev[k] !== undefined,
    );
    onUpdateMeasureDefaults(
      project.id,
      hasAny ? (prev as Project['measureDefaults']) : undefined,
    );
  };

export const ProjectOptionsSection = memo(function ProjectOptionsSection(): ReactNode {
  const {
    project,
    optionGroups,
    catalogs,
    updateProjectLevelChoice,
    onUpdateProjectLevelChoices,
    canEditContent,
  } = useProjectDetail();

  if (optionGroups.length === 0 || !onUpdateProjectLevelChoices) {
    return null;
  }

  // Closed quotes: hide project-level option editor (view-only).
  if (!canEditContent) {
    return null;
  }

  return (
    <section
      className="project-detail__section project-level-options"
      aria-label="Opciones del proyecto"
      data-testid="project-level-options"
    >
      <div className="project-detail__section-header">
        <h3 className="project-detail__section-title">Opciones del proyecto</h3>
      </div>
      <p className="project-editor__hint">
        Defaults de cotización. Cada mueble las hereda salvo que overridees en
        la línea.
      </p>
      <div className="project-item-choices">
        {optionGroups.map((group) => {
          const options = optionsForGroup(group, catalogs);
          return (
            <div key={group.id} className="catalog-form__field">
              <label htmlFor={`project-level-${group.code}`}>
                {group.name} ({group.code})
              </label>
              <select
                id={`project-level-${group.code}`}
                value={project.projectLevelChoices?.[group.code] ?? ''}
                onChange={(e) =>
                  updateProjectLevelChoice(group.code, e.target.value)
                }
                data-testid={`project-level-choice-${group.code}`}
              >
                <option value="">Sin default</option>
                {options.map((opt) => (
                  <option key={opt.id} value={opt.id}>
                    {opt.name} — {opt.code}
                  </option>
                ))}
              </select>
            </div>
          );
        })}
      </div>
    </section>
  );
});

export function BoardFinishPickers({
  groups,
  choices,
  onChange,
  testId = 'board-finish-pickers',
}: BoardFinishPickersProps): ReactNode {
  if (groups.length === 0) return null;

  return (
    <div className="board-finish-pickers" data-testid={testId}>
      <p
        className="catalog-form__hint board-finish-pickers__intro"
        data-testid={`${testId}-intro`}
      >
        Acabados de preview (solo esta vista 3D — no guarda la cotización):
      </p>
      {groups.map((g) => {
        const selected = choices[g.code] ?? g.options[0]?.id ?? '';
        const selectedOpt = g.options.find((o) => o.id === selected);
        return (
          <div
            key={g.code}
            className="catalog-form__field board-finish-pickers__field"
            data-testid={`${testId}-group-${g.code}`}
          >
            <label htmlFor={`${testId}-${g.code}`}>
              {g.name}
              {selectedOpt?.grainDefault ? ' · veta' : ''}
            </label>
            <div className="board-finish-pickers__control">
              {selectedOpt?.previewColor ? (
                <span
                  className="board-finish-pickers__swatch"
                  aria-hidden
                  title={selectedOpt.previewColor}
                  style={{ background: selectedOpt.previewColor }}
                />
              ) : null}
              <select
                id={`${testId}-${g.code}`}
                className="board-finish-pickers__select"
                value={selected}
                onChange={(e) => onChange(g.code, e.target.value)}
                data-testid={`${testId}-select-${g.code}`}
              >
                {g.options.map((o) => (
                  <option key={o.id} value={o.id}>
                    {o.code} — {o.name}
                    {o.grainDefault ? ' (veta)' : ''}
                  </option>
                ))}
              </select>
            </div>
          </div>
        );
      })}
    </div>
  );
}

export function CostPreviewPanel({
  costPreview,
  previewBlocked,
  missingGroups,
  groupLabels,
  allowEmptyHint,
  previewError,
}: CostPreviewPanelProps): ReactNode {
  if (allowEmptyHint && !costPreview && !previewBlocked) {
    return (
      <p className="catalog-empty catalog-empty--flush">
        Guardá el mueble para ver el preview de costo con defaults de opción.
      </p>
    );
  }

  return (
    <div
      className={
        previewBlocked || !costPreview
          ? 'module-cost-preview module-cost-preview--blocked'
          : 'module-cost-preview'
      }
      role="status"
      aria-live="polite"
    >
      <h4 className="module-cost-preview__title">
        Preview de costo (con opciones por defecto)
      </h4>
      {previewBlocked || !costPreview ? (
        <>
          <p className="module-cost-preview__blocked-msg">
            Preview bloqueado: faltan grupos o no se pudo calcular.
          </p>
          {missingGroups.length > 0 ? (
            <ul className="module-cost-preview__missing">
              {missingGroups.map((code) => (
                <li key={code}>{groupLabels?.[code] ?? code}</li>
              ))}
            </ul>
          ) : null}
          {previewError ? (
            <p className="module-cost-preview__blocked-msg">
              {previewError}
            </p>
          ) : null}
        </>
      ) : (
        <>
          <dl className="module-cost-preview__grid">
            <div>
              <dt>Materiales</dt>
              <dd>{formatModuleMoney(costPreview.materialsCost)}</dd>
            </div>
            <div>
              <dt>Cantos</dt>
              <dd>{formatModuleMoney(costPreview.edgeTotal)}</dd>
            </div>
            <div>
              <dt>Herrajes</dt>
              <dd>{formatModuleMoney(costPreview.hardwareTotal)}</dd>
            </div>
            <div>
              <dt>Costo directo</dt>
              <dd>{formatModuleMoney(costPreview.directCost)}</dd>
            </div>
